#nullable enable
using System.Collections.Immutable;
using Marten.Events.Projections;
using HourBooking.Contracts;

namespace HourBooking.Views;

/// <summary>
/// Context: booking. Slice: my-timesheet. One document per (employee, month), declared as
/// identity="employeeId, month" on the read model.
///
/// The model lists MyTimesheet's fields FLAT — employeeId, month, monthStatus, bookingId, projectId,
/// date, hours, note, dayTotal — because a read model in Event Modeling describes the shape a screen
/// needs, not a table schema. Here that becomes a month document holding lines, and the grain was not
/// really a free choice: monthStatus comes from BookingMonthStarted / MonthClosed, which carry no
/// bookingId, so a row-per-booking projection has nothing to group them by. The constraint decided it.
///
/// projectName is deliberately absent. It was removed from this view once because the row it belongs
/// to is created by a different event than the one carrying it — see blind spot 2 in
/// OPEN-QUESTIONS.md — so the screen reads names from MyProjects and joins on projectId.
///
/// Registered INLINE: updated in the same transaction as the append, so a GWT's THEN is assertable
/// the moment the request returns.
/// </summary>
public sealed record MyTimesheet
{
    public string Id { get; init; } = default!;

    public Guid EmployeeId { get; init; }
    public string Month { get; init; } = default!;

    /// <summary>
    /// derived="monthStatus=BookingMonthStarted+MonthClosureSubmitted+MonthClosureRejected+MonthClosed".
    /// A fold over which events have OCCURRED — "Open" is the absence of a closure event, which no
    /// rename could ever reach. That is exactly why derived= exists as its own thing.
    /// </summary>
    public string MonthStatus { get; init; } = "NotStarted";

    public ImmutableList<Line> Lines { get; init; } = ImmutableList<Line>.Empty;

    public sealed record Line(Guid BookingId, Guid ProjectId, DateOnly Date, decimal Hours, string? Note)
    {
        /// <summary>derived="dayTotal=hours" — a SUM, which is why it is not a mapping.</summary>
        public decimal DayTotal { get; init; }
    }

    public static string RowId(Guid employeeId, string month) => $"{employeeId}:{month}";

    /// <summary>Recomputed after every change, because dayTotal is a fold and not a carried value.</summary>
    private MyTimesheet WithDayTotals()
    {
        var byDay = Lines.GroupBy(l => l.Date).ToDictionary(g => g.Key, g => g.Sum(l => l.Hours));
        return this with { Lines = Lines.Select(l => l with { DayTotal = byDay[l.Date] }).ToImmutableList() };
    }

    internal MyTimesheet Upsert(Line line) =>
        (this with { Lines = Lines.RemoveAll(l => l.BookingId == line.BookingId).Add(line) }).WithDayTotals();

    internal MyTimesheet Remove(Guid bookingId) =>
        (this with { Lines = Lines.RemoveAll(l => l.BookingId == bookingId) }).WithDayTotals();

    internal MyTimesheet Correct(Guid bookingId, decimal hours, string? note)
    {
        var line = Lines.FirstOrDefault(l => l.BookingId == bookingId);
        return line is null ? this : Upsert(line with { Hours = hours, Note = note });
    }
}

public sealed class MyTimesheetProjection : MultiStreamProjection<MyTimesheet, string>
{
    public MyTimesheetProjection()
    {
        // Every one of these carries employeeId + month, which is the only reason this view is
        // projectable at all — and it is why month had to be added to all four Timesheet events when
        // the stream key was decided.
        Identity<BookingMonthStarted>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<MonthClosureSubmitted>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<MonthClosureRejected>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<MonthClosed>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<HoursBooked>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<HoursCorrected>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<BookingRemoved>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
        Identity<ZeroHoursFilled>(e => MyTimesheet.RowId(e.EmployeeId, e.Month));
    }

    public static MyTimesheet Apply(BookingMonthStarted e, MyTimesheet current) =>
        current with { EmployeeId = e.EmployeeId, Month = e.Month, MonthStatus = "Open" };

    /// <summary>
    /// "A submitted month is still open and can still be booked into and corrected. Only closing stops
    /// editing." So Submitted is a status the screen shows, not a gate.
    /// </summary>
    public static MyTimesheet Apply(MonthClosureSubmitted e, MyTimesheet current) =>
        current with { MonthStatus = "Submitted" };

    public static MyTimesheet Apply(MonthClosureRejected e, MyTimesheet current) =>
        current with { MonthStatus = "Rejected" };

    public static MyTimesheet Apply(MonthClosed e, MyTimesheet current) =>
        current with { MonthStatus = "Closed" };

    public static MyTimesheet Apply(HoursBooked e, MyTimesheet current) =>
        current.Upsert(new MyTimesheet.Line(e.BookingId, e.ProjectId, e.Date, e.Hours, e.Note));

    public static MyTimesheet Apply(HoursCorrected e, MyTimesheet current) =>
        current.Correct(e.BookingId, e.Hours, e.Note);

    public static MyTimesheet Apply(BookingRemoved e, MyTimesheet current) =>
        current.Remove(e.BookingId);

    public static MyTimesheet Apply(ZeroHoursFilled e, MyTimesheet current) =>
        current.Upsert(new MyTimesheet.Line(e.BookingId, e.ProjectId, e.Date, e.Hours, null));
}
